function get(tag,num) {
    const { java, source, cookie, cache } = this;
    var get = JSON.parse(source.getVariable());
    var Url = get['url'].replace(/www/, 'nnv3api') + '/classify/filter.json';
    var list = JSON.parse(java.ajax(Url));
    if (/theme/.test(tag)) {
        theme = list[0].items[num].tag_id;
    }
    if (/cate/.test(tag)) {
        cate = list[1].items[num].tag_id;
    }
    if (/status/.test(tag)) {
        status = list[2].items[num].tag_id;
    }
    if (/zone/.test(tag)) {
        zone = list[3].items[num].tag_id;
    }
    var e = eval(tag);
    return e;
}
